#!/usr/bin/env python3
"""Trim 5% from the left of fanart generated by rebuildMovieFanartFromPoster.py."""

import json
import os
import sqlite3
import stat
import subprocess
import tempfile
from pathlib import Path

from rebuildMovieFanartFromPoster import image_size, safe_artwork_path


DB = Path('/nascabos_data/database/nascab_video.db')


def main():
    db = sqlite3.connect(f'file:{DB}?mode=ro', uri=True)
    rows = db.execute("SELECT path, poster_path, fanart_path FROM video_index WHERE media_type IN ('movie','bdmv','video_ts') AND poster_path <> '' AND fanart_path <> ''").fetchall()
    pairs = {}
    for directory, poster, fanart in rows:
        directory = Path(directory)
        source = safe_artwork_path(directory, poster)
        target = safe_artwork_path(directory, fanart)
        if source and target and source != target and source.is_file() and target.is_file():
            pairs[target] = source
    done = 0
    skipped = 0
    failed = []
    for target, source in pairs.items():
        temporary = None
        try:
            post_width, post_height = image_size(source)
            width, height = image_size(target)
            if (width, height) != (post_width - post_width // 2, post_height):
                skipped += 1
                continue
            left = width * 5 // 100
            with tempfile.NamedTemporaryFile(prefix='.fanart-trim-', suffix='.jpg', dir=target.parent, delete=False) as handle:
                temporary = Path(handle.name)
            subprocess.run(['ffmpeg', '-hide_banner', '-loglevel', 'error', '-nostdin', '-y', '-i', str(target), '-vf', f'crop={width-left}:{height}:{left}:0:exact=1', '-frames:v', '1', '-q:v', '2', str(temporary)], check=True, capture_output=True)
            if image_size(temporary) != (width-left, height):
                raise ValueError('Unexpected crop dimensions')
            old = target.stat()
            os.chmod(temporary, stat.S_IMODE(old.st_mode))
            os.chown(temporary, old.st_uid, old.st_gid)
            os.replace(temporary, target)
            done += 1
            if done % 100 == 0:
                print(f'Trimmed {done}', flush=True)
        except Exception as error:
            failed.append(f'{target}: {error}')
        finally:
            if temporary:
                temporary.unlink(missing_ok=True)
    print(json.dumps({'trimmed': done, 'skipped': skipped, 'failed': failed}, ensure_ascii=False))
    return bool(failed)


if __name__ == '__main__':
    raise SystemExit(main())
